  if self.close_fault.is_some()||self.close_fault_retirement.is_some(){return Self::close_original_slot(&mut self.close_fault,&mut self.close_fault_retirement,grant,work)}
  if self.cleanup_fault.is_some()||self.cleanup_fault_retirement.is_some(){return Self::close_original_slot(&mut self.cleanup_fault,&mut self.cleanup_fault_retirement,grant,work)}
