  if let Some(owner)=self.job_output_retirement.as_mut(){if !owner.terminal_is_empty(){let demand=Self::nested(RetirementDemand{copy_bytes:owner.next_copy_byte_demand()?,capacity_bytes:owner.next_capacity_byte_demand(grant.maximum_copy_bytes)?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?})?;if !Self::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}*work=1;return owner.step(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant}).map(|step|RetainedCloneStep::Progress(step.progress()))}if !Self::permits(grant,RetirementDemand{depth:1,..Default::default()}){return Ok(RetainedCloneStep::Progress(Default::default()))}*work=1;drop(self.job_output_retirement.take());self.job_output_identity=None;self.job_output_offset=0;return Ok(metadata(false))}

