  if let Some(original)=self.value_retirement.as_mut(){if !original.terminal_is_empty(){let demand=Self::nested(RetirementDemand{copy_bytes:original.next_copy_byte_demand()?,capacity_bytes:original.next_capacity_byte_demand(grant.maximum_copy_bytes)?,release_bytes:original.next_release_byte_demand()?,depth:original.next_depth_demand()?})?;if !Self::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}*work=1;return original.step(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant}).map(|step|RetainedCloneStep::Progress(step.progress()))}if !Self::permits(grant,RetirementDemand{depth:1,..Default::default()}){return Ok(RetainedCloneStep::Progress(Default::default()))}*work=1;drop(self.value_retirement.take());return Ok(metadata(false))}
